(() => {
  /* ---------- Vectors ---------- */
  const dot=(a,b)=>a[0]*b[0]+a[1]*b[1]+a[2]*b[2];
  const cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];
  const sub=(a,b)=>[a[0]-b[0],a[1]-b[1],a[2]-b[2]];
  const add=(a,b)=>[a[0]+b[0],a[1]+b[1],a[2]+b[2]];
  const scale=(a,s)=>[a[0]*s,a[1]*s,a[2]*s];
  const norm=a=>Math.hypot(a[0],a[1],a[2]);
  const unit=a=>scale(a,1/norm(a));
  const centroid=ps=>scale(ps.reduce(add,[0,0,0]),1/ps.length);

  // hatch along a face's longest edge, as an engraver follows the form
  function longest(verts,idx){
    let best=null,bl=0;
    for(let k=0;k<idx.length;k++){const e=sub(verts[idx[(k+1)%idx.length]],verts[idx[k]]);const l=norm(e);if(l>bl){bl=l;best=e;}}
    return unit(best);
  }
  // faces of the convex hull of a vertex set, each ordered around its outward normal
  function hullFaces(V){
    const faces=[],seen=new Set();
    for(let a=0;a<V.length;a++)for(let b=a+1;b<V.length;b++)for(let c=b+1;c<V.length;c++){
      let n=cross(sub(V[b],V[a]),sub(V[c],V[a])); if(norm(n)<1e-9)continue; n=unit(n);
      let d=dot(n,V[a]),pos=0,neg=0;
      for(const p of V){const s=dot(n,p)-d;if(s>1e-7)pos++;else if(s<-1e-7)neg++;}
      if(pos&&neg)continue; if(pos){n=scale(n,-1);d=-d;}
      const on=V.map((p,i)=>i).filter(i=>Math.abs(dot(n,V[i])-d)<1e-7), key=on.join(',');
      if(seen.has(key))continue; seen.add(key);
      const cen=centroid(on.map(i=>V[i])), u=unit(sub(V[on[0]],cen)), w=cross(n,u);
      on.sort((i,j)=>{const pi=sub(V[i],cen),pj=sub(V[j],cen);return Math.atan2(dot(pi,w),dot(pi,u))-Math.atan2(dot(pj,w),dot(pj,u));});
      faces.push({idx:on,n,hatch:longest(V,on)});
    }
    return faces;
  }
  function fit(verts,faces){
    const c=centroid(verts), R=Math.max(...verts.map(p=>norm(sub(p,c))));
    return {verts:verts.map(p=>scale(sub(p,c),1/R)),faces};
  }

  /* ---------- The three solids ---------- */
  // Dürer: a rhombohedron with 72° faces, its two sharp corners cut away
  function durer(){
    const th=72*Math.PI/180, h=Math.sqrt((2*Math.cos(th)+1)/3), r=Math.sqrt(1-h*h);
    const E=[0,1,2].map(i=>{const p=Math.PI/2+i*2*Math.PI/3;return[r*Math.cos(p),r*Math.sin(p),h];});
    const planes=[];
    for(const [i,j,k] of [[0,1,2],[1,2,0],[2,0,1]]){
      let n=cross(E[i],E[j]),K=dot(n,E[k]); if(K<0){n=scale(n,-1);K=-K;}
      planes.push({n:scale(n,-1),d:0},{n,d:K});
    }
    const cut=.5*h; planes.push({n:[0,0,-1],d:-cut},{n:[0,0,1],d:3*h-cut});
    const V=[];
    for(let a=0;a<planes.length;a++)for(let b=a+1;b<planes.length;b++)for(let c=b+1;c<planes.length;c++){
      const A=planes[a],B=planes[b],C=planes[c],det=dot(A.n,cross(B.n,C.n)); if(Math.abs(det)<1e-9)continue;
      const bc=cross(B.n,C.n),ca=cross(C.n,A.n),ab=cross(A.n,B.n);
      const p=scale([0,1,2].map(t=>A.d*bc[t]+B.d*ca[t]+C.d*ab[t]),1/det);
      if(planes.every(P=>dot(P.n,p)<=P.d+1e-9)&&!V.some(q=>norm(sub(q,p))<1e-7))V.push(p);
    }
    const m=fit(V,[]); m.faces=hullFaces(m.verts); return m;
  }
  // Leonardo: the rhombicuboctahedron, drawn hollow for Pacioli
  function rhombi(){
    const s=1+Math.SQRT2, V=[];
    for(const big of [0,1,2])for(const a of [-1,1])for(const b of [-1,1])for(const c of [-1,1]){
      const p=[a,b,c]; p[big]*=s; V.push(p);
    }
    const m=fit(V,[]); m.faces=hullFaces(m.verts); return m;
  }
  // Uccello: the mazzocchio, a faceted ring of 32 segments with an octagonal section
  function mazzocchio(){
    const U=32,W=8,R=1,r=.34,V=[],F=[];
    for(let i=0;i<U;i++)for(let j=0;j<W;j++){
      const u=2*Math.PI*i/U, v=2*Math.PI*j/W+Math.PI/W;
      V.push([(R+r*Math.cos(v))*Math.cos(u), r*Math.sin(v), (R+r*Math.cos(v))*Math.sin(u)]);
    }
    const id=(i,j)=>((i+U)%U)*W+((j+W)%W);
    for(let i=0;i<U;i++)for(let j=0;j<W;j++){
      const idx=[id(i,j),id(i+1,j),id(i+1,j+1),id(i,j+1)], ps=idx.map(k=>V[k]), c=centroid(ps);
      let n=unit(cross(sub(ps[2],ps[0]),sub(ps[3],ps[1])));
      const uc=2*Math.PI*(i+.5)/U, out=sub(c,[R*Math.cos(uc),0,R*Math.sin(uc)]);
      if(dot(n,out)<0){n=scale(n,-1);idx.reverse();}
      F.push({idx,n,hatch:unit(sub(V[id(i+1,j)],V[id(i,j)])),checker:(i+j)%2===1});
    }
    return fit(V,F);
  }
  // Escher: the impossible cube of Belvedere, a frame of eight corner blocks and twelve bars.
  // Each block keeps only its outer faces. The impossibility is a single lie in the painting order:
  // the back upright on the right is always painted just after the front top bar, so wherever the two
  // overlap the back one passes in front.
  function cube(){
    const t=.34, V=[], F=[], prisms=[];
    const FACES={'-z':[0,3,2,1],'+z':[4,5,6,7],'-y':[0,1,5,4],'+y':[3,7,6,2],'-x':[0,4,7,3],'+x':[1,2,6,5]};
    const N={'-z':[0,0,-1],'+z':[0,0,1],'-y':[0,-1,0],'+y':[0,1,0],'-x':[-1,0,0],'+x':[1,0,0]};
    const AX=[[1,0,0],[0,1,0],[0,0,1]], XYZ='xyz';
    function addBox(lo,hi,name,skip,along){
      const b=V.length,[x0,y0,z0]=lo,[x1,y1,z1]=hi;
      V.push([x0,y0,z0],[x1,y0,z0],[x1,y1,z0],[x0,y1,z0],[x0,y0,z1],[x1,y0,z1],[x1,y1,z1],[x0,y1,z1]);
      const fs=[], gone=[...skip].map(k=>FACES[k]);
      for(const k in FACES){
        if(skip.has(k))continue;
        const n=N[k], normalAxis=XYZ.indexOf(k[1]), q=FACES[k];
        const a=along!==undefined&&along!==normalAxis?along:[0,1,2].find(i=>i!==normalAxis);
        // an edge on a joint between a bar and its corner is not cut, so each bar runs on through its corners
        const joint=q.map((v,e)=>gone.some(g=>g.includes(v)&&g.includes(q[(e+1)%4])));
        F.push({idx:q.map(i=>b+i),n,hatch:AX[a],joint}); fs.push(F.length-1);
      }
      prisms.push({name,faces:fs,verts:[0,1,2,3,4,5,6,7].map(i=>b+i)});
    }
    for(const cx of [-1,1])for(const cy of [-1,1])for(const cz of [-1,1]){
      const c=[cx,cy,cz], skip=new Set(c.map((v,i)=>(v>0?'-':'+')+XYZ[i]));
      addBox(c.map(v=>v-t/2),c.map(v=>v+t/2),'corner',skip);
    }
    for(let ax=0;ax<3;ax++){
      const o=[0,1,2].filter(i=>i!==ax);
      for(const a of [-1,1])for(const b of [-1,1]){
        const lo=[0,0,0],hi=[0,0,0];
        lo[ax]=-1+t/2; hi[ax]=1-t/2; lo[o[0]]=a-t/2; hi[o[0]]=a+t/2; lo[o[1]]=b-t/2; hi[o[1]]=b+t/2;
        const name=XYZ[ax]+(a>0?'+1':'-1')+(b>0?'+1':'-1');
        addBox(lo,hi,name,new Set(['-'+XYZ[ax],'+'+XYZ[ax]]),ax);
      }
    }
    const R=Math.sqrt(3)*(1+t/2);
    return {verts:V.map(p=>scale(p,1/R)),faces:F,prisms,lie:{back:'y+1-1',front:'x+1+1'}};
  }
  const SOLIDS={durer,rhombi,mazzocchio,cube};
  const POSE={
    durer:{base:-2.3,yaw:.9,pitch:.38,style:'solid',f:2.05,cx:.47,edge:1.35},
    rhombi:{base:0,yaw:.42,pitch:.4,style:'hollow',f:1.95,cx:.5,edge:1.1},
    mazzocchio:{base:0,yaw:.25,pitch:.6,style:'checker',f:2.05,cx:.5,edge:.8},
    cube:{base:0,yaw:.62,pitch:.48,style:'frame',f:1.9,cx:.5,edge:1}
  };
  const L=unit([-.5,1.0,.35]);
  // the chosen theme, or the system's when none has been chosen
  const isDark=()=>{const t=document.documentElement.getAttribute('data-theme');return t?t==='dark':matchMedia('(prefers-color-scheme: dark)').matches;};
  const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;

  function hull2(pts){
    pts=pts.slice().sort((a,b)=>a[0]-b[0]||a[1]-b[1]);
    const cr=(o,a,b)=>(a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0]);
    const lo=[],up=[];
    for(const p of pts){while(lo.length>1&&cr(lo[lo.length-2],lo[lo.length-1],p)<=0)lo.pop();lo.push(p);}
    for(const p of pts.reverse()){while(up.length>1&&cr(up[up.length-2],up[up.length-1],p)<=0)up.pop();up.push(p);}
    return lo.slice(0,-1).concat(up.slice(0,-1));
  }

  /* ---------- One engraved plate on one canvas ---------- */
  function Plate(cv){
    const kind=cv.dataset.plate, S=SOLIDS[kind](), P0=POSE[kind], ctx=cv.getContext('2d');
    let yaw=P0.yaw,pitch=P0.pitch,reveal=reduce?1:0;
    const rot=p=>{
      let [x,y,z]=p,c=Math.cos(P0.base),s=Math.sin(P0.base);
      [y,z]=[y*c-z*s,y*s+z*c];
      c=Math.cos(pitch);s=Math.sin(pitch);[y,z]=[y*c-z*s,y*s+z*c];
      c=Math.cos(yaw);s=Math.sin(yaw);[x,z]=[x*c+z*s,-x*s+z*c];
      return [x,y,z];
    };
    const trace=poly=>{poly.forEach((q,i)=>i?ctx.lineTo(q[0],q[1]):ctx.moveTo(q[0],q[1]));ctx.closePath();};
    function hatch(region,dir,spacing,width,frac,seed){
      const perp=[-dir[1],dir[0]]; let lo=Infinity,hi=-Infinity;
      for(const q of region[0]){const t=q[0]*perp[0]+q[1]*perp[1];lo=Math.min(lo,t);hi=Math.max(hi,t);}
      const n=Math.floor((hi-lo)/spacing),shown=Math.ceil(n*frac); if(shown<1)return;
      ctx.save();ctx.beginPath();region.forEach(trace);ctx.clip('evenodd');
      ctx.lineWidth=width;ctx.beginPath();
      for(let k=1;k<=shown;k++){
        const t=lo+k*spacing+Math.sin((k+1)*12.9898*seed)*.22, bx=perp[0]*t, by=perp[1]*t;
        ctx.moveTo(bx-dir[0]*4000,by-dir[1]*4000);ctx.lineTo(bx+dir[0]*4000,by+dir[1]*4000);
      }
      ctx.stroke();ctx.restore();
    }
    function draw(){
      const W=cv.clientWidth,H=cv.clientHeight; if(!W)return;
      const dpr=Math.min(devicePixelRatio||1,2.5);
      if(cv.width!==Math.round(W*dpr)){cv.width=Math.round(W*dpr);cv.height=Math.round(H*dpr);}
      ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,W,H);
      const st=getComputedStyle(document.body), ink=st.color, paper=st.backgroundColor;
      const dark=isDark();
      ctx.strokeStyle=ink;ctx.lineCap='round';ctx.lineJoin='round';
      const D=5.2,f=W*P0.f,cx=W*P0.cx,cy=H*.5;
      const proj=p=>[cx+f*p[0]/(D-p[2]),cy-f*p[1]/(D-p[2])];
      const P=S.verts.map(rot),Q=P.map(proj);

      // the cast shadow, hatched level, and a stroke of floor
      const g=Math.min(...P.map(p=>p[1]));
      const sh=hull2(P.map(p=>{const t=(p[1]-g)/L[1];return proj([p[0]-L[0]*t,g,p[2]-L[2]*t]);}));
      hatch([sh],[1,0],dark?5.2:2.1,dark?.45:.7,Math.min(1,reveal*1.6),3.1);
      ctx.lineWidth=.8;ctx.beginPath();
      const fl=proj([-1.3,g,.35]),fr=proj([1.4,g,.35]);ctx.moveTo(fl[0],fl[1]);ctx.lineTo(fr[0],fr[1]);ctx.stroke();

      const hollow=P0.style==='hollow';
      const faceOf=(F,fi)=>{const n=rot(F.n),p=P[F.idx[0]];return {F,fi,n,front:dot(n,sub([0,0,D],p))>0,depth:F.idx.reduce((s,i)=>s+P[i][2],0)/F.idx.length};};
      let order;
      if(S.prisms){
        const blocks=S.prisms.map(pr=>({pr,depth:pr.verts.reduce((s,i)=>s+P[i][2],0)/pr.verts.length})).sort((a,b)=>a.depth-b.depth);
        const bi=blocks.findIndex(b=>b.pr.name===S.lie.back), fi=blocks.findIndex(b=>b.pr.name===S.lie.front);
        if(bi<fi){const [b]=blocks.splice(bi,1); blocks.splice(fi,0,b);}
        order=[]; blocks.forEach(b=>b.pr.faces.forEach(i=>{const o=faceOf(S.faces[i],i); if(o.front) order.push(o);}));
      } else {
        order=S.faces.map(faceOf).filter(o=>hollow||o.front).sort((a,b)=>a.depth-b.depth);
      }

      for(const o of order){
        const outer=o.F.idx.map(i=>Q[i]);
        let region=[outer];
        if(hollow){
          // Leonardo's hollow form: each face is a frame, open in the middle
          const c=centroid(o.F.idx.map(i=>P[i]));
          region=[outer,o.F.idx.map(i=>proj(add(c,scale(sub(P[i],c),.56)))).reverse()];
        }
        ctx.save();ctx.fillStyle=paper;ctx.beginPath();region.forEach(trace);ctx.fill('evenodd');ctx.restore();

        // light on the face; inner faces of the hollow form sit in shade
        const nn=o.front?o.n:scale(o.n,-1);
        let lit=Math.max(0,dot(nn,L))*(o.front?1:.55);
        let shade=1-lit;
        if(o.F.checker) shade=Math.min(1,shade+.42);   // the mazzocchio's alternate facets
        // on the dark plate, lines read as light, so density follows light instead of shade
        const b=dark?Math.min(.86,shade):1-shade, tone=1-b;
        const p0=P[o.F.idx[0]],hd=rot(o.F.hatch),a=proj(p0),z=proj(add(p0,scale(hd,.3)));
        let dir=[z[0]-a[0],z[1]-a[1]];const dl=Math.hypot(dir[0],dir[1])||1;dir=[dir[0]/dl,dir[1]/dl];
        const local=Math.max(0,Math.min(1,reveal*1.5-(o.fi%4)*.12));
        const fine=P0.style==='checker'?.8:1;
        if(b<.93) hatch(region,dir,(2.3+7.2*Math.pow(b,1.35))*fine,.5+.55*tone,local,o.fi+1);
        if(tone>.58){const c=Math.cos(.95),s=Math.sin(.95);hatch(region,[dir[0]*c-dir[1]*s,dir[0]*s+dir[1]*c],(2.6+4*(1-tone))*fine,.45,local,o.fi+7);}
        ctx.lineWidth=P0.edge;ctx.beginPath();
        if(o.F.joint){ outer.forEach((q,e)=>{ if(o.F.joint[e])return; const r=outer[(e+1)%outer.length]; ctx.moveTo(q[0],q[1]); ctx.lineTo(r[0],r[1]); }); }
        else region.forEach(trace);
        ctx.stroke();
      }
    }
    // the solid is engraved and turns into place at the same time, once, when it comes into view
    let turning=false;
    function start(){
      if(reveal>=1){draw();return;}
      const t0=performance.now(); turning=true;
      const step=now=>{
        if(!turning)return;
        const k=Math.min(1,(now-t0)/1900);
        reveal=1-Math.pow(1-k,2.2); yaw=P0.yaw-.5*Math.pow(1-k,3);
        draw(); if(k<1)requestAnimationFrame(step); else turning=false;
      };
      requestAnimationFrame(step);
    }
    // drag, or the arrow keys, turn the solid
    let drag=null;
    cv.addEventListener('pointerdown',e=>{drag=[e.clientX,e.clientY];cv.setPointerCapture(e.pointerId);if(turning){turning=false;yaw=P0.yaw;}reveal=1;draw();});
    cv.addEventListener('pointermove',e=>{if(!drag)return;yaw+=(e.clientX-drag[0])*.011;pitch=Math.max(-1.2,Math.min(1.2,pitch+(e.clientY-drag[1])*.011));drag=[e.clientX,e.clientY];draw();});
    const end=()=>{drag=null;};cv.addEventListener('pointerup',end);cv.addEventListener('pointercancel',end);
    cv.addEventListener('keydown',e=>{
      const k={ArrowLeft:[-.12,0],ArrowRight:[.12,0],ArrowUp:[0,-.12],ArrowDown:[0,.12]}[e.key];
      if(!k)return;e.preventDefault();if(turning){turning=false;yaw=P0.yaw;}reveal=1;yaw+=k[0];pitch=Math.max(-1.2,Math.min(1.2,pitch+k[1]));draw();
    });
    addEventListener('resize',draw);
    matchMedia('(prefers-color-scheme: dark)').addEventListener('change',draw);
    addEventListener('themechange',draw);
    (document.fonts?document.fonts.ready:Promise.resolve()).then(()=>{
      if(reduce||!('IntersectionObserver' in window)){start();return;}
      yaw=P0.yaw-.5; draw();
      const io=new IntersectionObserver(es=>{if(es.some(e=>e.isIntersecting)){io.disconnect();start();}},{threshold:.3});
      io.observe(cv);
    });
  }
  document.querySelectorAll('canvas.plate').forEach(cv=>{
    if(!SOLIDS[cv.dataset.plate]) return;
    try{ Plate(cv); }catch(e){ console.error('Plate',cv.dataset.plate,e); }
  });
})();
